  highlightedText = "The data unequivocally demonstrates that prior constraints on energy transfer were vastly underestimated, opening new pathways for sustainable technologies.",
  paragraph2 = "Following the announcement, institutional laboratories across the globe have initiated verification protocols. While skepticism remains among some traditionalist circles, the preliminary replication results are promising. This discovery not only challenges established doctrines but also promises practical applications that could revolutionize industry standards within the next decade.",
  sideHeadline = "Economic Shifts Predict New Market Realities",
  sideText = "As global markets respond to recent technological advancements, analysts project a steady realignment of major industry sectors. Investment strategies are rapidly adapting to accommodate the influx of new data.",
  highlightColor = "#fcee0a",
  textColor = "#1a1a1a",
  zoomAmount = 1.6,
  zoomOriginX = 35,
  zoomOriginY = 55,
  grainOpacity = 0.08,
  highlight1X = 1.5,
  highlight1Y = -2,
  highlight1Thickness = 54,
  highlight1Length = 98,
  highlight2X = 1.5,
  highlight2Y = 48,
  highlight2Thickness = 54,
  highlight2Length = 96,
